(()=>{'use strict';const form=document.querySelector('#blog-search-form');if(!form)return;const toggle=document.querySelector('.blog-search-toggle'),input=document.querySelector('#blog-query'),cards=[...document.querySelectorAll('.blog-card')],empty=document.querySelector('.blog-empty'),feature=document.querySelector('[data-feature]');let sport='all';const normalize=s=>s.normalize('NFKC').toLocaleLowerCase().trim();function filter(){let count=0;const query=normalize(input.value);for(const card of cards){const show=(sport==='all'||card.dataset.sport===sport)&&normalize(card.dataset.search+' '+card.textContent).includes(query);card.hidden=!show;if(show)count++;}empty.hidden=count>0;feature.hidden=sport!=='all'||query.length>0;}toggle.addEventListener('click',()=>{form.hidden=!form.hidden;toggle.setAttribute('aria-expanded',String(!form.hidden));if(!form.hidden)input.focus();});form.addEventListener('submit',e=>{e.preventDefault();filter();});input.addEventListener('input',filter);for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{sport=button.dataset.filter;for(const b of document.querySelectorAll('[data-filter]'))b.setAttribute('aria-pressed',String(b===button));filter();});})();
